def reverse_words(s):
    chars = list(s)
    reverse(chars, 0, len(chars) - 1)
    start = 0
    for i in range(len(chars) + 1):
        if i == len(chars) or chars[i] == " ":
            reverse(chars, start, i - 1)
            start = i + 1
    return "".join(chars)

