static String reverseWords(String s) {
    char[] chars = s.toCharArray();
    int n = chars.length;
    reverse(chars, 0, n - 1);
    int start = 0;
    for (int i = 0; i <= n; i++) {
        if (i == n || chars[i] == ' ') {
            reverse(chars, start, i - 1);
            start = i + 1;
        }
    }
    return new String(chars);
}

