def gcd(a, b):
    while b:
        a, b = b, a % b
    return a


def rotate_left_cycles(a, k):
    n = len(a)
    if n == 0:
        return a
    k %= n
    for start in range(gcd(n, k)):
        carry = a[start]
        i = start
        while True:
            j = (i + k) % n
            if j == start:
                break
            a[i] = a[j]
            i = j
        a[i] = carry
    return a

