static int[] rotateLeftCycles(int[] a, int k) {
    int n = a.length;
    if (n == 0) return a;
    k %= n;
    for (int start = 0; start < gcd(n, k); start++) {
        int carry = a[start], i = start;
        while (true) {
            int j = (i + k) % n;
            if (j == start) break;
            a[i] = a[j];
            i = j;
        }
        a[i] = carry;
    }
    return a;
}

